      if (q.options.some(o => normalize(o.text) === normalize(raw))) return [raw];
      const labels = raw.replace(/^(?:正确答案|参考答案|答案|选项)\s*[:：]?\s*/i, '')
        .replace(/^\[([\s\S]*)\]$/, '$1').trim();
